252	/* ─── Icon Button ───────────────────────────────────────────── */
253	/*
254	 * Icon-only buttons carry a subtle warm-grey outline at rest (--icon-border)
255	 * to signal interactivity without the visual weight of a full tertiary border.
256	 * Hover/active apply a light background fill; the outline darkens slightly as
257	 * a secondary cue. Two color variants (constructive, destructive) and a
258	 * pressed/toggled state for stateful on/off controls.
259	 *
260	 * Production requirements:
261	 *   - Always provide aria-label on the <button>
262	 *   - Always set aria-hidden="true" on the icon element / SVG
263	 *   - Use the framework tooltip (OverlayTrigger/Tooltip in React Bootstrap;
264	 *     <Tooltip> in MUI) — not the HTML title attribute — so the label is
265	 *     visible on both hover and keyboard focus.
266	 *   - For toggle controls, set aria-pressed="true"/"false" on the <button>
267	 */
268	
269	.btn-icon {
270	  display: inline-flex;
271	  align-items: center;
272	  justify-content: center;
273	  box-sizing: border-box;
274	  background: transparent;
275	  border: 1px solid var(--icon-border); /* subtle outline — clarifies click affordance */
276	  border-radius: 6px;
277	  cursor: pointer;
278	  color: var(--grey);
279	  line-height: 1;
280	  flex-shrink: 0;
281	  padding: 0;
282	  transition: background-color 0.12s ease, border-color 0.12s ease, color 0.12s ease;
283	
284	  /* Standard size — height matches the standard text button */
285	  width: 36px;
286	  height: 36px;
287	  font-size: 18px;
288	}
289	
290	/* Compact — for inline field actions and table-row contexts */
291	.btn-icon.btn-icon-sm {
292	  width: 28px;
293	  height: 28px;
294	  font-size: 14px;
295	}
296	
297	.btn-icon:hover:not(:disabled) {
298	  background: var(--grey-hover-bg);
299	  border-color: var(--grey-dis);
300	  color: var(--grey-hover-dark);
301	}
302	
303	.btn-icon:active:not(:disabled) {
304	  background: var(--grey-active-bg);
305	  border-color: var(--grey-dis);
306	  color: var(--grey-hover-dark);
307	}
308	
309	.btn-icon:focus-visible {
310	  outline: 3px solid var(--focus-ring);
311	  outline-offset: 2px;
312	}
313	
314	.btn-icon:disabled {
315	  border-color: var(--icon-border);
316	  color: var(--grey-dis);
317	  cursor: not-allowed;
318	}
319	
320	/* Constructive variant — edit, add, copy actions */
321	.btn-icon.btn-icon-constructive {
322	  color: var(--sec-border);
323	}
324	
325	.btn-icon.btn-icon-constructive:hover:not(:disabled) {
326	  background: var(--sec-bg);
327	  color: var(--sec-border-active);
328	}
329	
330	.btn-icon.btn-icon-constructive:active:not(:disabled) {
331	  background: var(--sec-bg-hover);
332	  color: var(--sec-border-active);
333	}
334	
335	/* Destructive icon variant — ghost red, for trash/remove icon buttons */
336	.btn-icon.btn-icon-destructive {
337	  color: var(--danger);
338	}
339	
340	.btn-icon.btn-icon-destructive:hover:not(:disabled) {
341	  background: var(--danger-ghost-hover);
342	  color: var(--danger-hover);
343	}
344	
345	.btn-icon.btn-icon-destructive:active:not(:disabled) {
346	  background: var(--danger-ghost-active);
347	  color: var(--danger-active);
348	}
349	
350	.btn-icon.btn-icon-destructive:disabled {
351	  color: var(--danger-dis-text);
352	}
353	
354	/* Pressed / toggled state */
355	.btn-icon[aria-pressed="true"],
356	.btn-icon.sim-pressed {
357	  background: var(--grey-active-bg);
358	  border-color: var(--grey-dis);
359	  color: var(--grey-hover-dark);
360	}
361	
362	.btn-icon[aria-pressed="true"]:hover:not(:disabled) {
363	  background: var(--grey-hover-bg);
364	  border-color: var(--grey-dis);
365	  color: var(--grey-hover-dark);
366	}
367	
368	/* Simulated states — documentation only */
369	.btn-icon.sim-hover               { background: var(--grey-hover-bg); border-color: var(--grey-dis); color: var(--grey-hover-dark); }
370	.btn-icon.sim-active              { background: var(--grey-active-bg); border-color: var(--grey-dis); color: var(--grey-hover-dark); }
371	.btn-icon.sim-focus               { box-shadow: 0 0 0 3px var(--focus-ring); outline: none; }
372	.btn-icon.sim-disabled            { border-color: var(--icon-border); color: var(--grey-dis); pointer-events: none; }
373	.btn-icon.sim-pressed             { background: var(--grey-active-bg); border-color: var(--grey-dis); color: var(--grey-hover-dark); }
374	
375	.btn-icon.btn-icon-constructive.sim-hover  { background: var(--sec-bg);       color: var(--sec-border-active); }
376	.btn-icon.btn-icon-constructive.sim-active { background: var(--sec-bg-hover);  color: var(--sec-border-active); }
377	
378	.btn-icon.btn-icon-destructive.sim-hover  { background: var(--danger-ghost-hover);  color: var(--danger-hover); }
379	.btn-icon.btn-icon-destructive.sim-active { background: var(--danger-ghost-active); color: var(--danger-active); }
380	.btn-icon.btn-icon-destructive.sim-disabled { color: var(--danger-dis-text); pointer-events: none; }
381	
