908	          <span class="btn-spinner" aria-hidden="true"></span>
909	          Refreshing…
910	        </button>
911	        <button class="btn btn-tertiary is-loading" disabled>
912	          <span class="btn-spinner" aria-hidden="true"></span>
913	          Loading…
914	        </button>
915	        <button class="btn btn-destructive is-loading" disabled>
916	          <span class="btn-spinner" aria-hidden="true"></span>
