958	    (function () {
959	      const html = document.documentElement;
960	      const btnLight = document.getElementById('toggle-light');
961	      const btnDark  = document.getElementById('toggle-dark');
962	
963	      function setTheme(theme) {
964	        html.setAttribute('data-theme', theme);
965	        btnLight.classList.toggle('active', theme === 'light');
966	        btnDark.classList.toggle('active',  theme === 'dark');
967	      }
968	
969	      // Initialise to OS preference
970	      const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
971	      setTheme(prefersDark ? 'dark' : 'light');
972	
973	      btnLight.addEventListener('click', function () { setTheme('light'); });
974	      btnDark.addEventListener('click',  function () { setTheme('dark');  });
975	    })();
976	  </script>
